import {orderNote,pendingTasks,updateNotes} from './order-notes.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function installOrderNotes({getBox,saveOrder,toast}){
  const d=document.createElement('dialog');d.className='notes-dialog';document.body.append(d);let id=null,draft=[];
  function list(){d.querySelector('#notesTasks').innerHTML=draft.filter(t=>!t.removed).map(t=>`<div class="notes-task"><input type="checkbox" data-task-done="${esc(t.id)}" aria-label="完成待办 ${esc(t.text)}" ${t.done?'checked':''}><input class="${t.done?'task-done':''}" data-task-text="${esc(t.id)}" maxlength="300" aria-label="待办内容" value="${esc(t.text)}"><button type="button" class="text-button" data-task-remove="${esc(t.id)}">移除</button></div>`).join('')||'<p class="dialog-note">暂无待办，可在下方添加。</p>';d.querySelector('#notesRemoved').innerHTML=draft.filter(t=>t.removed).map(t=>`<p>${esc(t.text)} <button type="button" class="text-button" data-task-restore="${esc(t.id)}">恢复</button></p>`).join('');}
  function open(orderId){const o=getBox().orders.find(o=>o.id===orderId);if(!o){toast('订单已不存在');return;}id=o.id;draft=structuredClone(o.tasks||[]);d.innerHTML=`<div class="dialog-heading"><h2>订单备注与待办</h2><button class="quiet" type="button" data-notes-close>取消</button></div><p class="dialog-note">${esc(o.name)}</p><form id="notesForm"><label class="notes-label">订单备注 · 团员核对单可见<textarea id="orderNoteText" maxlength="2000" rows="4" placeholder="例如：特典卡随商品一起发出；请核对角色及数量">${esc(orderNote(o))}</textarea></label><h3>团长待办</h3><p class="dialog-note">仅在工具内提醒，不出现在团员核对单上。勾选表示已完成。</p><div id="notesTasks"></div><div class="notes-add"><input id="newTaskText" maxlength="300" aria-label="新待办内容" placeholder="例如：少到一张卡，需要联系卖家"><button type="button" class="quiet" id="addNoteTask">添加待办</button></div><details><summary>已移除的待办</summary><div id="notesRemoved"></div></details><p id="notesError" role="alert" class="warning"></p><div class="dialog-footer"><span class="dialog-note">点击保存后生效</span><button class="primary" type="submit">保存并关闭</button></div></form>`;list();if(!d.open)d.showModal();}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-notes-order],[data-notes-all]');if(!b)return;if(b.hasAttribute('data-notes-order'))open(b.dataset.notesOrder);else{const rows=pendingTasks(getBox());id=null;d.innerHTML=`<div class="dialog-heading"><h2>本箱待办 · ${rows.length} 项</h2><button class="quiet" data-notes-close>关闭</button></div><p class="dialog-note">${esc(getBox().name)} · 未完成的待办仅作提醒，不阻止结算。</p>${rows.map(t=>`<div class="pending-row"><div><strong>${esc(t.order)}</strong><p>${esc(t.text)}</p></div><button class="quiet" data-notes-order="${esc(t.orderId)}">处理</button></div>`).join('')}`;if(!d.open)d.showModal();}});
  d.addEventListener('input',e=>{if(e.target.dataset.taskText){draft.find(t=>t.id===e.target.dataset.taskText).text=e.target.value;}});
  d.addEventListener('change',e=>{if(e.target.dataset.taskDone){const t=draft.find(t=>t.id===e.target.dataset.taskDone);t.done=e.target.checked;e.target.closest('.notes-task').querySelector('[data-task-text]').classList.toggle('task-done',t.done);}});
  function add(){const input=d.querySelector('#newTaskText'),text=input.value.trim();if(!text)return;if(draft.length>=200){d.querySelector('#notesError').textContent='每单最多保存 200 项待办';return;}draft.push({id:crypto.randomUUID(),text,done:false});input.value='';list();}
  d.addEventListener('keydown',e=>{if(e.target.id==='newTaskText'&&e.key==='Enter'){e.preventDefault();add();}});
  d.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-notes-close'))d.close();if(b.id==='addNoteTask')add();if(b.dataset.taskRemove){draft.find(t=>t.id===b.dataset.taskRemove).removed=true;list();}if(b.dataset.taskRestore){draft.find(t=>t.id===b.dataset.taskRestore).removed=false;list();}});
  d.addEventListener('submit',e=>{if(e.target.id!=='notesForm')return;e.preventDefault();try{if(d.querySelector('#newTaskText').value.trim())add();const o=getBox().orders.find(o=>o.id===id);if(!o)throw Error('订单已不存在');saveOrder(updateNotes(o,d.querySelector('#orderNoteText').value,draft));d.close();toast('备注与待办已保存');}catch(e){d.querySelector('#notesError').textContent=e.message;}});
}
